/* one control socket per component, one opcode dispatch table, epoll-driven */
static const struct cmd { const char *name; int (*fn)(struct comp *, const char *, int); } cmds[] = {
  {"status", cmd_status}, {"pause", cmd_pause}, {"resume", cmd_resume}, {"reload", cmd_reload},
};
void control_ready(struct comp *c, int cfd) {
    char buf[256]; ssize_t n = recv(cfd, buf, sizeof buf - 1, 0);
    if (n <= 0) return;                                   /* EOF or EAGAIN: nothing to do */
    buf[n] = 0; char *id = strtok(buf, " ");
    for (size_t i = 0; i < ARRAY_SIZE(cmds); i++)
        if (!strcmp(cmds[i].name, buf)) { cmd_reply(cfd, id, cmds[i].fn(c, id, cfd)); return; }
    cmd_reply(cfd, id, -1);                               /* unknown command */
}
